import { fileTypeFromBuffer } from "file-type";
const MIME_MAP = {
    jpg: 'image/jpeg',
    jpeg: 'image/jpeg',
    png: 'image/png',
    webp: 'image/webp',
    gif: 'image/gif',
    mp3: 'audio/mpeg',
    ogg: 'audio/ogg',
    wav: 'audio/wav',
    m4a: 'audio/mp4',
    mp4: 'video/mp4',
    mkv: 'video/x-matroska',
    webm: 'video/webm',
    pdf: 'application/pdf',
    zip: 'application/zip',
    json: 'application/json'
};
function getMimeType(fileName) {
    const ext = fileName.slice((fileName.lastIndexOf('.') - 1 >>> 0) + 2).toLowerCase();
    const mimeType = MIME_MAP[ext];
    return (ext && mimeType) ? mimeType : null;
}
export async function getTypeAndExt(buffer) {
    try {
        const fileType = await fileTypeFromBuffer(buffer);
        if (!fileType?.ext || !fileType.mime) {
            throw new Error('Invalid File');
        }
        return fileType;
    }
    catch (error) {
        throw new Error('File Type check error');
    }
}
function resolveFileName(typeExt) {
    return typeExt.mime.slice(0, typeExt.mime.indexOf('/')) + '.' + typeExt.ext;
}
export async function upload(buffer, name = 'default.', opts, mimeType) {
    let resolvedMime = mimeType || getMimeType(name);
    if (!resolvedMime) {
        const typeExt = await getTypeAndExt(buffer);
        resolvedMime = typeExt.mime;
        name = resolveFileName(typeExt);
    }
    const form = new FormData();
    form.append('file', new Blob([buffer], { type: resolvedMime }), name);
    const url = new URL(opts.url);
    url.searchParams.set('apitoken', opts.apitoken);
    const response = await fetch(url, {
        method: 'POST',
        headers: {
            ...opts.headers
        },
        body: form
    });
    return (await response.json());
}
